public static class BomSourceFixtureBuilder {
 const string Folder="Assets/BOMIntegration/SourceFixtures",ScenePath=Folder+"/SourceFixtures.unity";
 [Serializable]sealed class Requirement{public string name,source_id,expected;}
 [Serializable]sealed class Requirements{public Requirement[] sources;public float blast_x=-6,blast_y=4.2f;}
 static readonly List<(BomAssetInstance,string)> requirements=new List<(BomAssetInstance,string)>();
 static Material Material(string name,Color color){string path=Folder+"/"+name+".mat";var result=AssetDatabase.LoadAssetAtPath<Material>(path);if(result==null){result=new Material(AssetDatabase.LoadAssetAtPath<Material>("Assets/BOMIntegration/NativeFallback.mat"));AssetDatabase.CreateAsset(result,path);}result.SetColor("_BaseColor",color);EditorUtility.SetDirty(result);return result;}
 static Mesh Store(Mesh mesh,string name){string path=Folder+"/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old==null){AssetDatabase.CreateAsset(mesh,path);return mesh;}EditorUtility.CopySerialized(mesh,old);UnityEngine.Object.DestroyImmediate(mesh);return old;}
 static BomAssetInstance Source(BomLevelAuthoring level,string name,Vector3 position,BomMotionPolicy motion,Material[] materials,Mesh mesh,Vector2 depth,string expected){
  var root=new GameObject(name);root.transform.SetParent(level.transform,false);root.transform.localPosition=position;if(mesh!=null){root.AddComponent<MeshFilter>().sharedMesh=mesh;root.AddComponent<MeshRenderer>().sharedMaterials=materials;}
  var source=root.AddComponent<BomAssetInstance>();source.AssetKey="source-fixture/"+name;source.VisualGroup=root.transform;source.Motion=motion;source.Damage=BomDamagePolicy.Destructible;source.FallbackDepth=depth;source.OriginalObjectPath=name;if(expected!=null)requirements.Add((source,expected));return source;
 }
 static BomPhysicsPart Rectangle(Transform root,Vector2 lo,Vector2 hi,string material="wood"){var part=root.gameObject.AddComponent<BomPhysicsPart>();part.Minimum=lo;part.Maximum=hi;part.MaterialKey=material;return part;}
 public static void CreateAndExport(){
  if(!AssetDatabase.IsValidFolder(Folder))AssetDatabase.CreateFolder("Assets/BOMIntegration","SourceFixtures");requirements.Clear();var scene=EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects,NewSceneMode.Single);var level=new GameObject("Source fixture authoring").AddComponent<BomLevelAuthoring>();level.LevelId="bom-source-fixtures-v1";level.NextIdentityDecimal="9007199254746001";
  level.SimulationBounds=new BomBounds2(new Vector2(-13,-4),new Vector2(13,13));level.KillBounds=new BomBounds2(new Vector2(-12,-3),new Vector2(12,12));level.CameraBounds=new BomBounds2(new Vector2(-12,-2),new Vector2(12,11));level.AimBounds=new BomBounds2(new Vector2(-12,-2),new Vector2(12,12));level.FragmentCullBounds=new BomBounds2(new Vector2(-20,-10),new Vector2(20,20));level.BombCleanupBounds=new BomBounds2(new Vector2(-15,-6),new Vector2(15,15));level.BombSpawnX=new Vector2(-11,11);level.BombSpawnHeight=11.5f;level.Spawns=new[]{new Vector2(-10,.565f),new Vector2(9,.565f),new Vector2(-3,.565f),new Vector2(3.5f,.565f)};
  var blue=Material("Blue exterior",new Color(.15f,.6f,.95f));var orange=Material("Orange sides",new Color(.9f,.4f,.12f));var gray=Material("Floor",new Color(.3f,.35f,.4f));
  string texturePath=Folder+"/UV checker.asset";var texture=AssetDatabase.LoadAssetAtPath<Texture2D>(texturePath);if(texture==null){texture=new Texture2D(16,16,TextureFormat.RGBA32,false){name="UV checker",filterMode=FilterMode.Point,wrapMode=TextureWrapMode.Repeat};for(int y=0;y<16;y++)for(int x=0;x<16;x++)texture.SetPixel(x,y,((x/4+y/4)&1)==0?Color.white:new Color(.48f,.48f,.48f,1));texture.Apply();AssetDatabase.CreateAsset(texture,texturePath);}blue.SetTexture("_BaseMap",texture);orange.SetTexture("_BaseMap",texture);
  var box=Store(BomExtrusion.Build(new[]{new Vector2(-.5f,-.5f),new Vector2(.5f,-.5f),new Vector2(.5f,.5f),new Vector2(-.5f,.5f)},1),"Closed box");
  var floor=Source(level,"Floor",new Vector3(0,-.5f,0),BomMotionPolicy.Fixed,new[]{gray,gray},box,new Vector2(-.5f,.5f),null);floor.transform.localScale=new Vector3(24,1,1);floor.Damage=BomDamagePolicy.Indestructible;Rectangle(floor.transform,new Vector2(-.5f,-.5f),new Vector2(.5f,.5f),"stone");
  var first=Source(level,"Closed box",new Vector3(-6,1.5f,0),BomMotionPolicy.Fixed,new[]{blue,blue},box,new Vector2(-1,1),"fragments");first.transform.localScale=new Vector3(3,3,2);Rectangle(first.transform,new Vector2(-.5f,-.5f),new Vector2(.5f,.5f));
  var lpoints=new[]{Vector2.zero,new Vector2(3,0),new Vector2(3,1),new Vector2(1,1),new Vector2(1,3),new Vector2(0,3)};var lmesh=Store(BomExtrusion.Build(lpoints,1),"Closed concave L");var l=Source(level,"Closed concave solid",new Vector3(-1,0,0),BomMotionPolicy.Fixed,new[]{orange,blue},lmesh,new Vector2(-.5f,.5f),"fragments");var lp=l.gameObject.AddComponent<BomPhysicsPart>();lp.Shape=BomProxyShape.Polygon;lp.Outline=lpoints;lp.MaterialKey="wood";
  var multi=Source(level,"Disconnected solid group",new Vector3(6,5,0),BomMotionPolicy.Fixed,null,null,new Vector2(-.5f,.5f),"fragments");for(int i=0;i<2;i++){var child=new GameObject("Closed solid "+i);child.transform.SetParent(multi.transform,false);child.transform.localPosition=new Vector3(i==0?-.75f:.75f,0,0);child.transform.localScale=new Vector3(.8f,1.4f,1);child.AddComponent<MeshFilter>().sharedMesh=box;child.AddComponent<MeshRenderer>().sharedMaterials=new[]{i==0?blue:orange,i==0?orange:blue};Rectangle(child.transform,new Vector2(-.5f,-.5f),new Vector2(.5f,.5f));}
  var material=Source(level,"Multi material moving solid",new Vector3(6,1.2f,0),BomMotionPolicy.Dynamic,new[]{blue,orange},box,new Vector2(-.5f,.5f),"fragments");material.transform.localScale=new Vector3(2,2,1);Rectangle(material.transform,new Vector2(-.5f,-.5f),new Vector2(.5f,.5f));
  var mirror=Source(level,"Mirrored solid",new Vector3(-6,7,0),BomMotionPolicy.Fixed,new[]{orange,blue},box,new Vector2(-.4f,.4f),"intact_or_fragments");mirror.transform.localRotation=Quaternion.Euler(0,0,15);mirror.transform.localScale=new Vector3(-2.2f,1.5f,.8f);Rectangle(mirror.transform,new Vector2(-.5f,-.5f),new Vector2(.5f,.5f));
  var quad=new Mesh{name="Deliberately open decorative quad"};quad.vertices=new[]{new Vector3(-.75f,-.75f,0),new Vector3(.75f,-.75f,0),new Vector3(.75f,.75f,0),new Vector3(-.75f,.75f,0)};quad.normals=new[]{Vector3.back,Vector3.back,Vector3.back,Vector3.back};quad.uv=new[]{Vector2.zero,Vector2.right,Vector2.one,Vector2.up};quad.triangles=new[]{0,2,1,0,3,2};quad.RecalculateBounds();var thin=Source(level,"Declared open surface",new Vector3(0,7,0),BomMotionPolicy.Fixed,new[]{orange},Store(quad,"Open quad"),new Vector2(-.25f,.25f),"fallback");Rectangle(thin.transform,new Vector2(-.75f,-.75f),new Vector2(.75f,.75f));thin.ApproximationNote="Open decorative surface intentionally uses a closed native rectangle with visible extrusion fallback.";
  Mesh rock=null;foreach(var asset in AssetDatabase.LoadAllAssetsAtPath("Assets/Game/Geometry/Rock.fbx"))if(asset is Mesh mesh){rock=mesh;break;}if(rock==null)throw new InvalidOperationException("Original rock render mesh missing");var actualRock=Source(level,"Original rock audit",new Vector3(-10,7,0),BomMotionPolicy.Fixed,new[]{gray},rock,new Vector2(-1,1),"intact_or_fragments");var bounds=rock.bounds;float rockScale=1.6f/Mathf.Max(bounds.size.x,bounds.size.y,bounds.size.z);actualRock.transform.localScale=Vector3.one*rockScale;actualRock.transform.localPosition=new Vector3(-10,7,0)-bounds.center*rockScale;actualRock.FallbackDepth=new Vector2(bounds.min.z*rockScale+actualRock.transform.localPosition.z,bounds.max.z*rockScale+actualRock.transform.localPosition.z);Rectangle(actualRock.transform,new Vector2(bounds.min.x,bounds.min.y),new Vector2(bounds.max.x,bounds.max.y),"stone");actualRock.ApproximationNote="The original Rock.fbx is uniformly scaled to a maximum span of 1.6 units and centered at (-10,7,0), because the initial scale extended beyond the test arena. Its XY proxy is an explicit render-bounds rectangle; the original importer and asset are unchanged.";
  var glueA=Source(level,"Glued source A",new Vector3(3,6.5f,0),BomMotionPolicy.Dynamic,new[]{blue,orange},box,new Vector2(-.5f,.5f),"intact_or_fragments");var glueB=Source(level,"Glued source B",new Vector3(4,6.5f,0),BomMotionPolicy.Dynamic,new[]{orange,blue},box,new Vector2(-.5f,.5f),"intact_or_fragments");level.Glue.Add(new BomGlueAuthoring{A=Rectangle(glueA.transform,new Vector2(-.5f,-.5f),new Vector2(.5f,.5f)),B=Rectangle(glueB.transform,new Vector2(-.5f,-.5f),new Vector2(.5f,.5f))});
  EditorSceneManager.SaveScene(scene,ScenePath);BomAuthoringIdentity.Assign(level);EditorSceneManager.SaveScene(scene,ScenePath);string output=Environment.GetEnvironmentVariable("BOM_SOURCE_LAYOUT_OUT");if(string.IsNullOrEmpty(output))throw new InvalidOperationException("Set BOM_SOURCE_LAYOUT_OUT");var registry=BomLevelExporter.Export(level,output);
  var session=new GameObject("Native source fixture session").AddComponent<BomClientBehaviour>();session.VisualRegistry=registry;session.Material=AssetDatabase.LoadAssetAtPath<Material>("Assets/BOMIntegration/NativeFallback.mat");session.PlayerPrefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/BOMIntegration/NativePlayer.prefab");session.BombPrefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/BOMIntegration/NativeBomb.prefab");var camera=UnityEngine.Object.FindFirstObjectByType<Camera>();camera.orthographic=true;camera.orthographicSize=8;camera.transform.position=new Vector3(0,4.5f,-40);camera.transform.rotation=Quaternion.identity;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.05f,.07f,.1f);session.View=camera;foreach(var renderer in level.GetComponentsInChildren<Renderer>(true))renderer.enabled=false;
  EditorSceneManager.SaveScene(scene,ScenePath);AssetDatabase.SaveAssets();var rows=new List<Requirement>();foreach(var item in requirements)rows.Add(new Requirement{name=item.Item1.name,source_id=item.Item1.IdentityText,expected=item.Item2});File.WriteAllText(output+".requirements.json",JsonUtility.ToJson(new Requirements{sources=rows.ToArray()},true));Debug.Log("BOM SOURCE FIXTURES EXPORTED "+output);
 }
 public static void BuildMono(){BomM7GeometryGate.Run();CreateAndExport();string output=Environment.GetEnvironmentVariable("BOM_SOURCE_PLAYER_OUT");if(string.IsNullOrEmpty(output))throw new InvalidOperationException("Set BOM_SOURCE_PLAYER_OUT");Directory.CreateDirectory(output);PlayerSettings.SetScriptingBackend(NamedBuildTarget.Standalone,ScriptingImplementation.Mono2x);var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{ScenePath},target=BuildTarget.StandaloneWindows64,locationPathName=Path.Combine(output,"BombSourceFixtures.exe"),options=BuildOptions.Development});if(report.summary.result!=BuildResult.Succeeded)throw new InvalidOperationException("Source fixture player build failed");Debug.Log("BOM SOURCE FIXTURE MONO BUILD PASS");}
}
